mapper.insert:
insert into carsale_stock_alert (user_id, vehicle_id, status)
values (#{userId}, #{vehicleId}, #{status})
ON DUPLICATE KEY UPDATE status = #{status}

mapper.update:
update carsale_stock_alert
status = #{status}, notify_time = #{notifyTime},
where id = #{id}

mapper.select:
select id, user_id, vehicle_id, status, notify_time, create_time
from carsale_stock_alert

    and user_id = #{userId}
    and vehicle_id = #{vehicleId}
    and status = #{status}

order by create_time desc
